static const struct ri_face L_F = { 9u, 10u, 2u, 1u, L_G };

const struct ri_face *ri_face_by_id(int id) {
    if (id == RI_FACE_S)
        return &S_F;
    if (id == RI_FACE_M)
        return &M_F;
    if (id == RI_FACE_L)
        return &L_F;
    return 0;
}

const struct ri_face *ri_face_for_zoom(int z) {
    return ri_face_by_id(ri_face_id_for_zoom(z));
}

int ri_face_id_for_zoom(int z) {
    if (z == 1)
        return RI_FACE_M;
    if (z == 2)
        return RI_FACE_L;
    return RI_FACE_S; /* z0, compact (3) and anything else read smallest */
}

int ri_face_width(const struct ri_face *f, const char *s) {
    int w = 0;
    if (!f || !s)
        return 0;
    while (*s) {
        unsigned c = (unsigned char)*s++;
        if (c < 32u || c > 126u)
            continue;
        w += (int)f->g[c - 32u].w + (int)f->adv_gap;
    }
    return w;
}
